#!/usr/bin/env python3
"""R2.3 checks that are new: DRIVE / CREMI-2D aggregates (from the per-image record), the frozen mechanism audit, the IBI trace behind Fig. 4(b)
and S-D, regeneration of the generated figure sources, cross-references and citations.  Rows carry their kind (see vlib.py).
usage: verify_r23_numbers.py [TREE_ROOT] [--no-rerun]   (default root: parent of tools/)."""
import csv, glob, io, json, os, re, shutil, statistics as st, subprocess, sys, tempfile
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from vlib import Rec, tree_root
from drive_stats import compute, load
ROOT = tree_root(); RERUN = "--no-rerun" not in sys.argv
rd = lambda p: io.open(os.path.join(ROOT, p), encoding="utf-8").read()
main = rd("manuscript/ddfp_R2_1.tex"); sup = rd("manuscript/supplement_R2_1.tex")
nrm = lambda t: re.sub(r"\s+", " ", t.replace("~", " "))
R = Rec("verify_r23_numbers (R2.3: DRIVE/CREMI-2D recomputation, IBI trace, generated figures, cross-references)")

# ================= DRIVE (per-image record) =================
CSV = ROOT + "/evidence_drive/exp_b1_corrected.csv"
a = compute(CSV)
n, s_, d_, nv = a["naive_interp"], a["seq_fp"], a["ddfp"], a["no_interp"]
R.eq("RECOMPUTED", "DRIVE images per method", (nv["n"], n["n"], s_["n"], d_["n"]), (20, 20, 20, 20))
f2 = lambda x: "%.2f" % x
R.eq("RECOMPUTED", "DRIVE no_interp mean beta0^4 / beta0^8 / CC", (f2(nv["b4"]["mean"]), f2(nv["b8"]["mean"]), f2(nv["cc"]["mean"])), ("451.85", "3.60", "448.25"))
R.eq("RECOMPUTED", "DRIVE naive mean beta0^4 / beta0^8 / CC", (f2(n["b4"]["mean"]), f2(n["b8"]["mean"]), f2(n["cc"]["mean"])), ("3.60", "3.60", "0.00"))
R.eq("RECOMPUTED", "DRIVE seq_fp and ddfp mean beta0^4 / beta0^8", (f2(s_["b4"]["mean"]), f2(s_["b8"]["mean"]), f2(d_["b4"]["mean"]), f2(d_["b8"]["mean"])), ("451.85",) * 4)
R.eq("RECOMPUTED", "DRIVE no_interp DWC-critical blocks, total (images affected)", (int(nv["viol"]["sum"]), nv["imgs_with_viol"]), (9544, 20))
R.eq("RECOMPUTED", "DRIVE seq_fp / ddfp critical blocks, total", (int(s_["viol"]["sum"]), int(d_["viol"]["sum"])), (0, 0))
R.eq("RECOMPUTED", "DRIVE seq_fp == ddfp per image (counts, CC, chi, TSI, violations)", a["seq_ddfp_identical_20"], 20)
R.eq("RECOMPUTED", "DRIVE naive: TSI mean / chi_flip %", (f2(n["tsi_mean"]), round(n["chi_flip_pct"])), ("222.74", 95))
R.eq("RECOMPUTED", "DRIVE naive TSI population SD / max", (f2(n["tsi_sd"]), f2(n["tsi_max"])), ("144.15", "523.74"))
R.eq("RECOMPUTED", "DRIVE no_interp b0-consistency mean; ddfp b0-consistency; ddfp chi_flip", ("%.6f" % nv["b0c_mean"], "%.6f" % d_["b0c_mean"], d_["chi_flip_pct"]), ("0.017721", "1.000000", 0.0))
R.eq("RECOMPUTED", "DRIVE no_interp mean DWC violation rate (x1e-4, 2 decimals)", "%.2f" % (nv["viol_rate_mean"] / 1e-4), "3.63")
R.eq("RECOMPUTED", "DRIVE ratio of mean counts beta0^8(ddfp)/beta0^8(no_interp) rounded  [R2.2 text: 125; R2.3: 126]", round(d_["b8"]["mean"] / nv["b8"]["mean"]), 126)
R.eq("RECOMPUTED", "DRIVE all fields of no_interp, seq_fp, ddfp binary; naive real-valued", (nv["binary_imgs"], s_["binary_imgs"], d_["binary_imgs"], n["binary_imgs"]), (20, 20, 20, 0))
R.eq("RECOMPUTED", "DRIVE no_interp per-image ranges beta0^4, beta0^8, critical blocks (min/median/max)", ((nv["b4"]["min"], nv["b4"]["med"], nv["b4"]["max"]), (nv["b8"]["min"], nv["b8"]["med"], nv["b8"]["max"]), (nv["viol"]["min"], nv["viol"]["med"], nv["viol"]["max"])), ((36, 435.5, 1059), (1, 3, 19), (41, 457.5, 1102)))
for t, name, derived in (("$451.85$", "beta0^4 mean", True), ("$3.60$", "beta0^8 mean", True), ("CC\\,$=448.25$", "CC", True), ("TSI\\,$=222.74$", "naive TSI", True),
                          ("$3.63\\times10^{-4}$", "violation rate", True), ("$b_0$-consistency\\,$=0.017721$", "b0-consistency", True), ("about $126$ (ratio of the mean counts", "fragmentation factor", True)):
    R.text("DRIVE main text contains " + t + " (" + name + ")", t, main, derived)
tab = rd("manuscript/figsrc/drive_core_table.tex")
for t in ("9{,}544 (20/20)", "451.85 & 3.60 & 448.25", "222.74 & 95\\%", "0 (0/20)"):
    R.text("main-text table contains " + t, t, tab, derived=True)
R.add("DEFINITION", "main-text table was generated by tools/gen_drive_tables.py (rows are not typed)", "gen_drive_tables" in rd("tools/build_r23.sh"))

# ---- frozen mechanism audit vs record ----
J = json.load(open(ROOT + "/evidence_drive/FIG4_DWC_MECHANISM_SUMMARY_FROZEN.json")); fa = J["frozen_audit"]
R.eq("RECOMPUTED", "frozen audit: total no_interp violations == record sum", fa["no_interp_total_violations"], int(nv["viol"]["sum"]))
R.eq("RECOMPUTED", "frozen audit: mean violation rate == record mean of rounded rates (4 s.f.)", "%.4g" % fa["no_interp_mean_violation_rate"], "%.4g" % nv["viol_rate_mean"])
rk = a["no_interp_violation_rank"]
R.eq("RECOMPUTED", "case 33_manual1: rank among 20 and critical blocks", rk["33_manual1.gif"], (J["selection_rank_one_based"], J["case_no_interp_violation_count"]))
R.eq("RECOMPUTED", "selection ranks 6/10/15 of 20 for 38_/21_/33_manual1", (rk["38_manual1.gif"][0], rk["21_manual1.gif"][0], rk["33_manual1.gif"][0]), (6, 10, 15))
crit = lambda b: b[0][0] == b[1][1] and b[0][1] == b[1][0] and b[0][0] != b[0][1]
R.add("DEFINITION", "2x2 block: raw 10/01 is critical, Sequential FP and DD-FP 10/00 are not (criterion applied to the frozen JSON)", crit(J["raw_2x2"]) and not crit(J["sequential_fp_2x2"]) and not crit(J["ddfp_2x2"]))
R.text("Fig. 6 caption: case, anchor, rank, count", "case \\texttt{33\\_manual1}; anchor $(y,x)=(572,512)$). The case is the pre-specified 75th-percentile case by the number of DWC-critical blocks without interpolation (rank 15 of 20, 659 blocks)", main, derived=True)

# ---- CREMI 2D ----
cr = [r for r in csv.DictReader(open(CSV)) if r["dataset"] == "cremi"]
by = lambda m: [r for r in cr if r["preprocessing"] == m]
R.eq("RECOMPUTED", "CREMI-2D patches per method", tuple(len(by(m)) for m in ("no_interp", "naive_interp", "seq_fp", "ddfp")), (50, 50, 50, 50))
v66 = sum(int(r["dwc_violations"]) for r in by("no_interp"))
R.eq("RECOMPUTED", "CREMI-2D no_interp violating face blocks (total) / patches affected", (v66, sum(1 for r in by("no_interp") if int(r["dwc_violations"]) > 0)), (66, 35))
R.eq("RECOMPUTED", "CREMI-2D ddfp and seq_fp violations; ddfp TSI", (sum(int(r["dwc_violations"]) for r in by("ddfp")), sum(int(r["dwc_violations"]) for r in by("seq_fp")), max(float(r["tsi"]) for r in by("ddfp"))), (0, 0, 0.0))
R.eq("RECOMPUTED", "CREMI-2D recorded rate = mean of per-patch rates stored to six decimals (x1e-6, 1 decimal)", "%.1f" % (st.mean(float(r["dwc_viol_rate"]) for r in by("no_interp")) / 1e-6), "5.2")
blocks = {(int(r["interp_h"]) - 1) * (int(r["interp_w"]) - 1) for r in by("no_interp")}
R.eq("RECOMPUTED", "CREMI-2D face blocks per 511x511 field", blocks, {260100})
R.eq("RECOMPUTED", "CREMI-2D pooled rate violations / blocks (x1e-6, 1 decimal)", "%.1f" % (v66 / (50 * 260100) / 1e-6), "5.1")
for t in ("recorded aggregate DWC violation rate is $5.2\\times10^{-6}$", "66 violating face-blocks across 50 patches (recomputed as violations over the $260{,}100$ face blocks of each $511\\times511$ field the pooled rate is $5.1\\times10^{-6}$"):
    R.text("CREMI-2D text: " + t[:60], nrm(t), nrm(main), derived=True)
# DRIVE geometry sanity: block count of the frozen audit = 20 x (1167-1)(1129-1)
R.eq("RECOMPUTED", "DRIVE blocks per image (1167-1)(1129-1) x 20 == frozen audit total 2x2 blocks", 20 * (1167 - 1) * (1129 - 1), fa["total_2x2_blocks"])

# ================= IBI trace (Fig. 4b, S-D figures) =================
T = json.load(open(ROOT + "/evidence_ibi/trace_out.json"))
R.add("RECOMPUTED", "trace: SHA pins of the unmodified production files recorded as true", all(T["sha_pins_ok"].values()), str(T["sha_pins_ok"]))
d1 = [c for c in T["cases"] if c["delta"] == 1]; d2 = [c for c in T["cases"] if c["delta"] != 1]
R.eq("RECOMPUTED", "trace: cases (D,K,delta) read", [(c["D"], c["K"], c["delta"]) for c in T["cases"]], [(24, 3, 1), (23, 4, 1), (24, 3, 2)])
R.add("RECOMPUTED", "trace: every recorded seeded call (rounds 1,2; all cases) passed the production pin validator", all(call["pin_validator"] == "accepts" for c in T["cases"] for call in c["calls"] if call["round"] >= 1))
R.eq("RECOMPUTED", "trace: R* returned (all cases)", [c["R_star_returned"] for c in T["cases"]], [2, 2, 2])
pin_lo, pin_up, owners = set(), set(), set()
for c in d1:
    sl = c["slabs"]
    for call in c["calls"]:
        if call["round"] < 1: continue
        k = call["k"]; pins = set(call["pinned_rows_global"]); exp = set()
        if k < c["K"] - 1: exp |= {2 * sl[k][1] + o for o in (0, 1)}
        if k > 0: exp |= {2 * sl[k - 1][1] + o for o in (-2, -1, 0)}
        R_ok = pins == exp
        if not R_ok: R.add("RECOMPUTED", "trace: pinned rows of case D=%d round %d window %d" % (c["D"], call["round"], k), False, "%s vs %s" % (sorted(pins), sorted(exp)))
        pin_lo.add(R_ok)
    for m in c["seam_owner_map"]:
        owners.add(tuple(sorted((int(k), v - m["seam_k"]) for k, v in m["owner_by_row_offset"].items())))
R.eq("RECOMPUTED", "trace: pinned rows == union of seam roles {0,+1} and {-2,-1,0} in every window/round of both delta=1 cases", pin_lo, {True})
R.eq("RECOMPUTED", "trace: owner by row offset (-2,-1 -> slab k; 0,+1 -> slab k+1), all seams of both cases", owners, {((-2, 0), (-1, 0), (0, 1), (1, 1))})
R.add("DEFINITION", "trace: the delta=2 case is in the record but not drawn (double ownership, S-D statement (d))", len(d2) == 1)
R.text("Fig. 4(b) caption states no theorem for seeded rounds", "no theorem is claimed for seeded rounds", main)
R.text("S-D scope table present", "Scope of the statements about Round~0 and about IBI", sup)

# ================= regenerated figure sources =================
if RERUN:
    with tempfile.TemporaryDirectory() as tmp:
        for dname in ("evidence_ibi", "evidence_drive"): os.symlink(os.path.join(ROOT, dname), os.path.join(tmp, dname))
        os.makedirs(tmp + "/figures/source"); shutil.copytree(ROOT + "/figures/generators", tmp + "/figures/generators")
        for gen, out in (("gen_fig4.py", "fig4_partition_ibi.tex"), ("gen_fig6.py", "fig6_dwc_main.tex")):
            r = subprocess.run([sys.executable, "-I", tmp + "/figures/generators/" + gen], capture_output=True, text=True)
            same = r.returncode == 0 and open(tmp + "/figures/source/" + out).read() == open(ROOT + "/figures/source/" + out).read()
            R.add("RERUN", "%s regenerated from the trace / frozen audit -> %s identical to the shipped source (asserts inside the generator passed)" % (gen, out), same, r.stderr[-150:])
        tabdir = tmp + "/tab"
        r = subprocess.run([sys.executable, "-I", ROOT + "/tools/gen_drive_tables.py", CSV, tabdir], capture_output=True, text=True)
        same = r.returncode == 0 and all(open(tabdir + "/" + f).read() == open(ROOT + "/manuscript/figsrc/" + f).read() for f in ("drive_core_table.tex", "drive_perimage_table.tex"))
        R.add("RERUN", "gen_drive_tables.py regenerated -> both table sources identical to the built manuscript", same, r.stderr[-150:])

# ================= cross-references and citations =================
def pdftext(p):
    return subprocess.run(["pdftotext", os.path.join(ROOT, p), "-"], capture_output=True, text=True).stdout
pm, ps = pdftext("manuscript/ddfp_R2_1.pdf"), pdftext("manuscript/supplement_R2_1.pdf")
R.eq("RECOMPUTED", "'??' (unresolved reference) in main / supplement PDF", (pm.count("??"), ps.count("??")), (0, 0))
for logf in ("ddfp_R2_1.log", "supplement_R2_1.log"):
    lg = rd("manuscript/" + logf); R.eq("RECOMPUTED", "LaTeX warnings 'undefined' in " + logf, lg.count("undefined"), 0)
xs = rd("manuscript/xref_S.tex"); xm = rd("manuscript/xref_M.tex")
nocom = lambda t: re.sub(r"(?<!\\)%[^\n]*", "", t)
used_S = set(re.findall(r"\\xS\{([^}]+)\}", nocom(main))); used_M = set(re.findall(r"\\xM\{([^}]+)\}", nocom(sup + main)))
R.add("RECOMPUTED", "every \\xS label used in the main text exists in the supplement (%d labels)" % len(used_S), all("xS@%s\\endcsname" % l in xs for l in used_S), str(sorted(l for l in used_S if "xS@%s\\endcsname" % l not in xs)))
R.add("RECOMPUTED", "every \\xM label used in the supplement exists in the main text (%d labels)" % len(used_M), all("xM@%s\\endcsname" % l in xm for l in used_M), str(sorted(l for l in used_M if "xM@%s\\endcsname" % l not in xm)))
# resolved number must belong to a caption of the expected title (the number is read from the other document's PDF text)
def cap_check(pdf, label_to_prefix, xref):
    ok = True; det = []
    for lab, (word, prefix) in label_to_prefix.items():
        m = re.search(r"csname x[SM]@%s\\endcsname\{%s~([A-Z]?\d+)\}" % (re.escape(lab), word), xref)
        if not m: ok = False; det.append(lab + ": no number"); continue
        num = m.group(1); hit = re.search(re.escape(word) + r"\s+" + re.escape(num) + r"[:.]?\s+" + re.escape(prefix[:24]).replace(r"\ ", r"\s+"), pdf)
        if not hit: ok = False; det.append("%s -> %s %s: caption '%s' not found" % (lab, word, num, prefix[:24]))
    return ok, "; ".join(det)
ok, det = cap_check(ps, {"fig:S-dwc-mechanism": ("Figure", "Representative resolution"), "fig:S-qualitative": ("Figure", "Cross-modality qualitative"), "fig:S-ibi-seam": ("Figure", "Seam geometry of a seeded round"),
                        "fig:S-ibi-decomp": ("Figure", "What the verification decomposition"), "fig:S-dep": ("Figure", "Dependencies of the proof"), "tab:S-scope": ("Table", "Scope of the statements"), "alg:D1": ("Algorithm", "Optional IBI refinement")}, xs)
R.add("RECOMPUTED", "supplement labels cited from the main text point at the intended captions (number read from the aux, caption found in the PDF)", ok, det)
ok, det = cap_check(pm, {"fig:partition": ("Figure", "Work sets and assembly"), "fig:worklist": ("Figure", "What parallel execution"), "fig:levels": ("Figure", "Why FP must be able"), "algo:gpufp": ("Algorithm", "GpuFP"), "algo:round0": ("Algorithm", "Round 0: slab-wise"), "fig:dwc-mechanism": ("Figure", "Local mechanism of DWC")}, xm)
R.add("RECOMPUTED", "main-text labels cited from the supplement point at the intended captions", ok, det)
# hard-coded Figure/Table/Algorithm numbers (outside macros) -- allowlist: external works, history
allow = ("Boutry", "Algorithm~1, Propositions", "Algorithm~1 and Propositions", "it was Algorithm~3 of the R2.1 main text", "Algorithm S1")
hard = []
for f in sorted(glob.glob(ROOT + "/sources/p*.tex")) + [ROOT + "/manuscript/supplement_R2_1.tex"]:
    for i, l in enumerate(io.open(f, encoding="utf-8").read().split("\n"), 1):
        l2 = re.sub(r"(?<!\\)%.*", "", l)
        if re.search(r"\\x[SM]\{|\\cref|\\Cref", l2) and False: continue
        for m in re.finditer(r"(Figure|Fig\.|Table|Tab\.|Algorithm|Alg\.)[~ ]*(S?\d+|D\d+)\b", l2):
            ctx = l2[max(0, m.start() - 70):m.end() + 40]
            if not any(a_ in ctx for a_ in allow): hard.append("%s:%d %s" % (os.path.basename(f), i, m.group(0)))
R.add("RECOMPUTED", "no hard-coded Figure/Table/Algorithm numbers in the sources (allowlist: Boutry's Algorithm 1, history notes)", not hard, "; ".join(hard[:6]))
# citations
cites = set(); [cites.update(k.strip() for k in g.split(",")) for g in re.findall(r"\\cite[a-z]*\{([^}]+)\}", re.sub(r"(?<!\\)%.*", "", main))]
bib = set(re.findall(r"\\bibitem(?:\[[^\]]*\])?\{([^}]+)\}", main))
R.eq("RECOMPUTED", "citations: distinct keys cited / bibitems / uncited bibitems / missing", (len(cites), len(bib), len(bib - cites), len(cites - bib)), (31, 31, 0, 0))
sys.exit(R.report(os.path.join(ROOT, "review", "VERIFY_r23_numbers.md") if os.path.isdir(os.path.join(ROOT, "review")) else None))
